INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('1f6038ef-fc7c-4f57-bb86-782ad6e71207', '4-1', 'NB', 'TIN HOC 12 - BAI 1', 'Trí tuệ nhân tạo (AI) có khả năng thực hiện công việc nào sau đây?', '{"A":{"text":"Chỉ thực hiện công việc có tính lặp lại.","image":""},"B":{"text":"Làm công việc trí tuệ của con người như đọc chữ, hiểu tiếng nói.","image":""},"C":{"text":"Chỉ thực hiện các phép tính cơ bản.","image":""},"D":{"text":"Không thực hiện được công việc trí tuệ.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:35', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('421ec4b3-2e9c-4fbe-accf-e16492e6593c', '4-1', 'NB', 'TIN HOC 12 - BAI 1', 'Đặc trưng nào của AI giúp máy tính nắm bắt thông tin từ dữ liệu và điều chỉnh hành vi?', '{"A":{"text":"Khả năng suy luận.","image":""},"B":{"text":"Khả năng giải quyết vấn đề.","image":""},"C":{"text":"Khả năng học.","image":""},"D":{"text":"Khả năng nhận thức.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:35', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('5efaf996-8fc0-46d5-9b0e-4b9ea20f09a7', '4-1', 'NB', 'TIN HOC 12 - BAI 1', 'Ví dụ nào sau đây thể hiện khả năng học của AI?', '{"A":{"text":"Hệ thống khuyến nghị trên YouTube dựa vào lịch sử xem.","image":""},"B":{"text":"Hệ thống chẩn đoán y tế dựa trên các triệu chứng.","image":""},"C":{"text":"Máy tính điều khiển xe tự lái.","image":""},"D":{"text":"Dự báo thời tiết dựa trên dữ liệu trước đây.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:35', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('f5af4991-4eec-4454-86ee-348e9ef89ae3', '4-1', 'NB', 'TIN HOC 12 - BAI 1', 'Khả năng suy luận của AI được thể hiện ở ứng dụng nào sau đây?', '{"A":{"text":"Nhận dạng khuôn mặt.","image":""},"B":{"text":"Dịch thuật tự động.","image":""},"C":{"text":"Hệ thống chẩn đoán y tế.","image":""},"D":{"text":"Nhận diện tiếng nói.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:35', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('36cd735d-f25b-46d7-b488-5a9d3a437f7d', '4-1', 'NB', 'TIN HOC 12 - BAI 1', 'Đặc trưng nào giúp AI cảm nhận và hiểu biết môi trường xung quanh?', '{"A":{"text":"Khả năng học.","image":""},"B":{"text":"Khả năng suy luận.","image":""},"C":{"text":"Khả năng nhận thức.","image":""},"D":{"text":"Khả năng hiểu ngôn ngữ.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:35', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('f5eff22e-268c-4c9c-9a76-6141170810b5', '4-1', 'NB', 'TIN HOC 12 - BAI 1', 'AI có thể thực hiện nhiệm vụ nào sau đây thông qua khả năng hiểu ngôn ngữ?', '{"A":{"text":"Đọc văn bản và dịch thuật.","image":""},"B":{"text":"Dự đoán thời tiết.","image":""},"C":{"text":"Nhận dạng hình ảnh.","image":""},"D":{"text":"Xử lý hóa đơn.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:35', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('c413fda7-9367-44d3-a3fc-3d8c0da3800f', '4-1', 'NB', 'TIN HOC 12 - BAI 1', 'Hệ chuyên gia MYCIN là một ứng dụng của AI trong lĩnh vực nào sau đây?', '{"A":{"text":"Giáo dục.","image":""},"B":{"text":"Y học.","image":""},"C":{"text":"Thương mại điện tử.","image":""},"D":{"text":"Giao thông.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
