INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('0855b546-6dec-4937-bc30-a2299f44b72b', '4-1', 'NB', 'TIN HOC 12 - BAI 1', 'Hội thảo nào sau đây được coi là điểm mốc ghi nhận sự ra đời của thuật ngữ AI, đánh dấu sự khởi đầu của lĩnh vực AI, thúc đẩy sự phát triển của lĩnh vực này trong các năm tiếp theo?', '{"A":{"text":"Hội thảo Hampshire.","image":""},"B":{"text":"Hội thảo Bletchley.","image":""},"C":{"text":"Hội thảo Dartmouth.","image":""},"D":{"text":"Hội thảo Jenesys.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('6b30d25b-ffd7-4165-85a9-80a0a85c76ef', '4-1', 'NB', 'TIN HOC 12 - BAI 1', 'Hệ thống nào dưới đây không được coi là hệ thống có ứng dụng AI?', '{"A":{"text":"Google Translate.","image":""},"B":{"text":"ChatGPT.","image":""},"C":{"text":"Dây chuyền lắp ráp tự động.","image":""},"D":{"text":"Dự báo thời tiết.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('a0cfb71f-8c03-4433-8410-30489a8a39b9', '4-1', 'TH', 'TIN HOC 12 - BAI 1', 'Trong các khả năng của AI, khả năng nào sau đây cho phép hệ thống tự động điều chỉnh hành vi?', '{"A":{"text":"Khả năng suy luận.","image":""},"B":{"text":"Khả năng học.","image":""},"C":{"text":"Khả năng nhận thức.","image":""},"D":{"text":"Khả năng giải quyết vấn đề.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
