INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('51a08a1b-f109-437a-a4cc-45386df7287d', '4-1', 'TH', 'TIN HOC 12 - BAI 1', 'Nhận dạng khuôn mặt là ứng dụng AI với đặc trưng nào sau đây?', '{"A":{"text":"Khả năng học và nhận thức.","image":""},"B":{"text":"Khả năng giải quyết vấn đề.","image":""},"C":{"text":"Khả năng suy luận.","image":""},"D":{"text":"Khả năng hiểu ngôn ngữ.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
