INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('e5cc15e0-561c-47fe-9bc5-0fc526525f0c', '4-1', 'TH', 'TIN HOC 12 - BAI 1', 'Robot Asimo có thể di chuyển nhờ đặc trưng nào sau đây của AI?', '{"A":{"text":"Khả năng nhận thức.","image":""},"B":{"text":"Khả năng học.","image":""},"C":{"text":"Khả năng giải quyết vấn đề.","image":""},"D":{"text":"Khả năng suy luận.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('288a58b5-8570-4b2b-bfa8-a05e628bd6e4', '4-1', 'TH', 'TIN HOC 12 - BAI 1', 'Hệ thống khuyến nghị tích hợp trên YouTube là ví dụ về đặc trưng nào sau đây của AI?', '{"A":{"text":"Khả năng học.","image":""},"B":{"text":"Khả năng giải quyết vấn đề.","image":""},"C":{"text":"Khả năng hiểu ngôn ngữ.","image":""},"D":{"text":"Khả năng nhận thức.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('fc01d101-ea41-4dd1-bb8a-d53746774648', '4-1', 'TH', 'TIN HOC 12 - BAI 1', 'Máy tính điều khiển xe tự lái như thế nào?', '{"A":{"text":"Sử dụng cảm biến lidar và camera để phát hiện và nhận biết xe xung quanh, các chướng ngại vật, biển báo giao thông và người đi bộ trên đường.","image":""},"B":{"text":"Sử dụng cảm biến radar và siêu âm để phát hiện và nhận biết xe xung quanh, các chướng ngại vật, biển báo giao thông và người đi bộ trên đường.","image":""},"C":{"text":"Sử dụng cảm biến siêu âm và lidar để phát hiện và nhận biết xe xung quanh, các chướng ngại vật, biển báo giao thông và người đi bộ trên đường.","image":""},"D":{"text":"Sử dụng cảm biến radar và camera để phát hiện và nhận biết xe xung quanh, các chướng ngại vật, biển báo giao thông và người đi bộ trên đường.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('34d04116-583d-476b-a9e1-c9da3a5ae5af', '4-1', 'TH', 'TIN HOC 12 - BAI 1', 'Phát biểu nào sau đây sai?', '{"A":{"text":"Mục tiêu của việc phát triển ứng dụng AI là nhằm xây dựng các phần mềm giúp máy tính có được những năng lực trí tuệ như con người.","image":""},"B":{"text":"Chương trình máy tính chơi cờ là một ví dụ của trí tuệ nhân tạo mạnh.","image":""},"C":{"text":"Giữa AI và tự động hoá có sự khác biệt.","image":""},"D":{"text":"Mọi ứng dụng AI trong thực tế đều cần có sự kết hợp ở các mức độ khác nhau của những đặc trưng trí tuệ.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('64614877-1da4-48a9-aa27-fddb7d95c7ac', '4-1', 'TH', 'TIN HOC 12 - BAI 1', 'Trợ lí ảo có chức năng nào sau đây?', '{"A":{"text":"Tìm kiếm thông tin bằng tiếng nói của người dùng.","image":""},"B":{"text":"Nhận dạng khuôn mặt.","image":""},"C":{"text":"Nhận dạng chữ viết tay.","image":""},"D":{"text":"Kiểm tra lỗi chính tả.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('dd71a726-4556-4aa9-ac51-6818673d3646', '4-1', 'TH', 'TIN HOC 12 - BAI 1', 'Phát biểu nào sau đây đúng?', '{"A":{"text":"Hệ chuyên gia MYCIN sử dụng các kĩ thuật Học máy.","image":""},"B":{"text":"Google dịch là dịch vụ dịch thuật có trả phí do Google phát triển.","image":""},"C":{"text":"Các robot thông minh được coi là ứng dụng điển hình của AI trong lĩnh vực điều khiển.","image":""},"D":{"text":"Hệ thống nhận dạng khuôn mặt là một ví dụ của trí tuệ nhân tạo tổng quát.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('8d755f70-f414-4094-8184-ccecd09c11de', '4-1', 'VD', 'TIN HOC 12 - BAI 1', 'Khả năng nào sau đây của AI được tích hợp vào trợ lý ảo để nhận biết giọng nói của người dùng?', '{"A":{"text":"Khả năng nhận thức.","image":""},"B":{"text":"Khả năng học.","image":""},"C":{"text":"Khả năng suy luận.","image":""},"D":{"text":"Khả năng hiểu ngôn ngữ.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('b8b7ea35-9b99-4319-9b71-622cbfaeb469', '4-1', 'VD', 'TIN HOC 12 - BAI 1', 'Việc AI trong hệ thống chẩn đoán y tế sử dụng dữ liệu bệnh lý để đưa ra kết luận là ví dụ của khả năng nào sau đây?', '{"A":{"text":"Khả năng học.","image":""},"B":{"text":"Khả năng suy luận.","image":""},"C":{"text":"Khả năng nhận thức.","image":""},"D":{"text":"Khả năng giải quyết vấn đề.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('fb43feba-6e51-45f4-9bef-23d16031c0d5', '4-1', 'VD', 'TIN HOC 12 - BAI 1', 'Trí tuệ nhân tạo hẹp có đặc điểm nào sau đây?', '{"A":{"text":"Tự học và thích nghi với mọi tình huống.","image":""},"B":{"text":"Chỉ thực hiện một nhiệm vụ cụ thể.","image":""},"C":{"text":"Có khả năng hiểu ngôn ngữ tự nhiên.","image":""},"D":{"text":"Tự ra quyết định trong mọi tình huống.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
