INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('f41a2c50-c967-48cc-93ac-8f203440e8fa', '4-1', 'VD', 'TIN HOC 12 - BAI 1', 'Phương án nào sau đây là ứng dụng của AI trong lĩnh vực y học?', '{"A":{"text":"Dịch thuật.","image":""},"B":{"text":"Bảo mật thông tin.","image":""},"C":{"text":"Nhận dạng biển số xe.","image":""},"D":{"text":"Xác định các bất thường trên hình ảnh CT/MRI sọ não.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('12523039-14d3-4f5e-9a7c-ff364cb70bd7', '4-1', 'VD', 'TIN HOC 12 - BAI 1', 'Hệ thống phân tích tài chính thuộc loại trí tuệ nhân tạo nào?', '{"A":{"text":"Siêu trí tuệ nhân tạo.","image":""},"B":{"text":"Trí tuệ nhân tạo tổng quát.","image":""},"C":{"text":"Trí tuệ nhân tạo hẹp.","image":""},"D":{"text":"Trí tuệ nhân tạo mạnh.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('5af9f521-5714-4e14-b9d4-3d93ffa936ab', '4-1', 'VD', 'TIN HOC 12 - BAI 1', 'Siri không có tính năng nào sau đây?', '{"A":{"text":"Đặt báo thức.","image":""},"B":{"text":"Thanh toán hoá đơn.","image":""},"C":{"text":"Gọi điện thoại.","image":""},"D":{"text":"Tìm kiếm.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:38', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('eb64ddc0-1b30-4909-b949-8cc40d916be0', '4-1', 'VD', 'TIN HOC 12 - BAI 1', 'Phương án nào sau đây không phải là ứng dụng của AI trong lĩnh vực sản xuất?', '{"A":{"text":"Điều phối điều trị.","image":""},"B":{"text":"Quản lí tồn kho và dự báo nhu cầu.","image":""},"C":{"text":"Kiểm tra chất lượng sản phẩm.","image":""},"D":{"text":"Tối ưu hoá quá trình lắp ráp.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:38', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('e67644b9-d295-4663-a72f-e634150cd189', '4-1', 'VD', 'TIN HOC 12 - BAI 1', 'AI có lợi ích như thế nào đối với khoa học và nghiên cứu?', '{"A":{"text":"AI có thể tự động chấm điểm bài kiểm tra và phân loại học sinh dựa trên thành tích học tập.","image":""},"B":{"text":"AI có thể phân tích dữ liệu bệnh lí của bệnh nhân và đề xuất phương pháp điều trị hiệu quả nhất.","image":""},"C":{"text":"Các hệ thống AI được tích hợp vào dây chuyền sản xuất giúp tăng hiệu suất, giảm sai sót và tiết kiệm chi phí nhờ khả năng làm việc liên tục và không cần nghỉ ngơi.","image":""},"D":{"text":"AI được sử dụng để dự đoán các kết quả trong các lĩnh vực như thời tiết, tác động của biến đổi khí hậu và địa chất học.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:38', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('32d27267-7f45-4c60-b711-d73a233942be', '4-1', 'VD', 'TIN HOC 12 - BAI 1', 'Thị giác máy tính (tiếng Anh: Computer vision), là một lĩnh vực trong khoa học máy tính và trí tuệ nhân tạo (AI) tập trung vào việc phát triển phương pháp và công nghệ để máy tính có khả năng nhận diện, hiểu và xử lý hình ảnh và video một cách tự động. Thị giác máy tính sử dụng các thuật toán và mô hình học máy để phân tích và rút trích thông tin từ dữ liệu hình ảnh, như các đặc trưng, đối tượng, mối quan hệ và bối cảnh. Vậy theo em, thị giác máy tính thực hiện được tác vụ nào sau đây?', '{"A":{"text":"Dự báo thời tiết.","image":""},"B":{"text":"Tăng độ nét và làm mịn ảnh.","image":""},"C":{"text":"Phân tích hình ảnh y tế.","image":""},"D":{"text":"Nhận dạng giọng nói.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:38', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('644f5eb4-830b-44cd-818e-7908ff1a4da3', '4-1', 'NB', 'TIN 12 - BAI 2', 'Trí tuệ nhân tạo (AI) đang hỗ trợ trong lĩnh vực nào sau đây để tăng hiệu suất giao thông và giảm thiểu ùn tắc?', '{"A":{"text":"Nông nghiệp.","image":""},"B":{"text":"Y học.","image":""},"C":{"text":"Giao thông vận tải.","image":""},"D":{"text":"Tài chính.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('dd5155e4-d314-41bb-bf27-002654c45338', '4-1', 'NB', 'TIN 12 - BAI 2', 'Một trong những lợi ích chính của trí tuệ nhân tạo trong lĩnh vực y học là gì trong các ý nào sau đây?', '{"A":{"text":"Cải thiện hình ảnh y tế để giúp chẩn đoán chính xác hơn.","image":""},"B":{"text":"Quản lý dữ liệu bệnh nhân.","image":""},"C":{"text":"Giảm chi phí điều trị.","image":""},"D":{"text":"Phát triển các loại thuốc mới.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('edf725d7-9dc1-49ba-8d57-11f82d0c777b', '4-1', 'NB', 'TIN 12 - BAI 2', 'Hệ chuyên gia PXDE, ứng dụng của trí tuệ nhân tạo, hỗ trợ dự đoán loại bệnh nào sau đây?', '{"A":{"text":"Tiểu đường.","image":""},"B":{"text":"Ung thư phổi.","image":""},"C":{"text":"Bệnh tim mạch.","image":""},"D":{"text":"Sốt xuất huyết.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('ff0915c3-9f3e-4a80-959f-78028d8ac6fa', '4-1', 'NB', 'TIN 12 - BAI 2', 'AI đang được ứng dụng trong lĩnh vực tài chính để làm nhiệm vụ nào sau đây?', '{"A":{"text":"Quản lý công việc nhân viên.","image":""},"B":{"text":"Phân tích và xử lý dữ liệu để hỗ trợ quyết định đầu tư.","image":""},"C":{"text":"Dự đoán giá xăng dầu.","image":""},"D":{"text":"Điều khiển hệ thống giao thông.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('11253263-f60d-4480-baa0-5521bbf81a96', '4-1', 'NB', 'TIN 12 - BAI 2', 'IBM Watson for Oncology, một phần mềm ứng dụng AI, giúp nâng cao hiệu quả điều trị bệnh nào sau đây?', '{"A":{"text":"Viêm gan.","image":""},"B":{"text":"Ung thư.","image":""},"C":{"text":"Bệnh tim mạch.","image":""},"D":{"text":"Bệnh tiểu đường.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('3fb1e010-edae-4daa-841b-76e9b1a51a5c', '4-1', 'NB', 'TIN 12 - BAI 2', 'Trong ngành tài chính, Chatbot AI thường được sử dụng để làm gì?', '{"A":{"text":"Quản lý giao thông.","image":""},"B":{"text":"Tối ưu hóa quy trình chăm sóc khách hàng.","image":""},"C":{"text":"Dự đoán xu hướng thời tiết.","image":""},"D":{"text":"Hướng dẫn nông dân.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('6e668a91-ac88-4526-9669-f67bff5eb915', '4-1', 'NB', 'TIN 12 - BAI 2', 'NatureFresh sử dụng AI để thực hiện công việc nào trong nông nghiệp?', '{"A":{"text":"Quản lý tài chính.","image":""},"B":{"text":"Dự báo thu hoạch và năng suất cây trồng.","image":""},"C":{"text":"Phân tích dữ liệu nhân khẩu học.","image":""},"D":{"text":"Tạo ra giống cây trồng mới.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('993a7348-8ccb-4fa1-9e87-83686e32d551', '4-1', 'NB', 'TIN 12 - BAI 2', 'Trong sản xuất công nghiệp, AI được sử dụng với mục đích nào sau đây?', '{"A":{"text":"Phân tích xu hướng thời tiết.","image":""},"B":{"text":"Tự động hóa quá trình lắp ráp và kiểm tra chất lượng.","image":""},"C":{"text":"Quản lý tài chính doanh nghiệp.","image":""},"D":{"text":"Tăng cường bảo mật mạng.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('e69fa6ae-7fb3-4564-9183-beed523d6a07', '4-1', 'NB', 'TIN 12 - BAI 2', 'IoT là gì khái niệm về nội dung nào sau đây?', '{"A":{"text":"Công nghệ thông tin.","image":""},"B":{"text":"Học sâu.","image":""},"C":{"text":"Internet vạn vật.","image":""},"D":{"text":"Thị giác máy tính.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:36', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('40841bdb-be97-4613-bacb-6ee8b4af3342', '4-1', 'NB', 'TIN 12 - BAI 2', 'Thành tựu nào sau đây là một thành tựu của xử lí ngôn ngữ tự nhiên và thị giác máy tính?', '{"A":{"text":"Hệ thống tưới tiêu tự động.","image":""},"B":{"text":"Hệ thống phân tích dữ liệu.","image":""},"C":{"text":"Hệ thống lắp ráp tự động.","image":""},"D":{"text":"Hệ thống nhận dạng hình ảnh và video.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('3256bf2b-7be7-41a2-83d3-03b4f7cfead3', '4-1', 'NB', 'TIN 12 - BAI 2', 'ChatGPT được phát triển bởi hãng nào sau đây?', '{"A":{"text":"Apple.","image":""},"B":{"text":"OpenAI.","image":""},"C":{"text":"Microsoft.","image":""},"D":{"text":"Meta.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('851c2a30-3775-4804-9217-8971adfbabef', '4-1', 'TH', 'TIN 12 - BAI 2', 'Trong các cảnh báo về AI, mối nguy cơ nào có thể xảy ra nếu AI thu thập một lượng lớn dữ liệu cá nhân?', '{"A":{"text":"Ảnh hưởng quyền riêng tư.","image":""},"B":{"text":"Tăng cường học tập.","image":""},"C":{"text":"Tăng hiệu quả sản xuất.","image":""},"D":{"text":"Tạo ra công ăn việc làm.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('8546c8c8-e391-4697-92d1-9b1b405d4d4e', '4-1', 'TH', 'TIN 12 - BAI 2', 'Một trong những khả năng nổi bật của ChatGPT là khả năng nào sau đây?', '{"A":{"text":"Suy luận và tổng hợp tri thức.","image":""},"B":{"text":"Quản lý tài chính cá nhân.","image":""},"C":{"text":"Điều khiển thiết bị y tế.","image":""},"D":{"text":"Dự đoán năng suất cây trồng.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('1a40db5e-ebb9-416a-9b8b-aabe0159451e', '4-1', 'TH', 'TIN 12 - BAI 2', 'AI có khả năng nào sau đây trong lĩnh vực xử lý ngôn ngữ tự nhiên?', '{"A":{"text":"Đưa ra chẩn đoán bệnh.","image":""},"B":{"text":"Dịch thuật tự động.","image":""},"C":{"text":"Tối ưu hóa chuỗi cung ứng.","image":""},"D":{"text":"Quản lý hệ thống giao thông.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('c4edf451-76be-44c0-9677-9c4b753c6d9a', '4-1', 'TH', 'TIN 12 - BAI 2', 'Để đáp ứng nhu cầu cá nhân hoá học tập, AI trong giáo dục có khả năng nào sau đây?', '{"A":{"text":"Tư vấn pháp lý.","image":""},"B":{"text":"Đề xuất nội dung học tập phù hợp cho học sinh.","image":""},"C":{"text":"Giám sát hoạt động tài chính.","image":""},"D":{"text":"Quản lý giao thông.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('ce50b3cb-2a5c-4bd3-8f01-78dda640113c', '4-1', 'TH', 'TIN 12 - BAI 2', 'Sự phát triển của AI mang lại lợi ích như thế nào sau đây cho lĩnh vực giáo dục?', '{"A":{"text":"AI hỗ trợ tự động hoá cập nhật chứng từ, hoá đơn vào cơ sở dữ liệu của ngân hàng.","image":""},"B":{"text":"AI được sử dụng để phát triển các phương tiện tự lái, quản lí giao thông thông minh và định tuyến phương tiện vận tải.","image":""},"C":{"text":"Các trợ lí ảo học tập dựa trên AI có thể hỗ trợ học sinh và giáo viên bằng cách trả lời câu hỏi, cung cấp hướng dẫn và tài liệu học tập.","image":""},"D":{"text":"AI có thể giúp người nông dân tối ưu hoá quy trình chăm sóc vật nuôi và cây trồng.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('36f27a44-5d5b-46c7-a150-ecf942d0f171', '4-1', 'TH', 'TIN 12 - BAI 2', 'AI có ảnh hưởng như thế nào trong các phát biểu sau đối với lĩnh vực khoa học xã hội và nhân văn?', '{"A":{"text":"Với sự phát triển của AI, đặc biệt là Học máy, nhiều hệ chuyên gia đã có khả năng tự học từ dữ liệu để tự hình thành các luật tri thức dựa trên dữ liệu.","image":""},"B":{"text":"AI được sử dụng để mô phỏng và mô hình hoá nhiều hiện tượng xã hội vân nhân học.","image":""},"C":{"text":"AI được sử dụng để cải thiện chất lượng hình ảnh y tế.","image":""},"D":{"text":"AI giúp tự động hoá nhiều quá trình, từ chế tạo, lắp ráp, kiểm tra chất lượng đến quản lí chuỗi cung ứng.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('a74f5d42-a402-4fef-bee5-520887a78569', '4-1', 'TH', 'TIN 12 - BAI 2', 'Sự kết hợp IoT và AI (AIoT) giúp ích cho các nhà khoa học như thế nào trong các phát biểu sau đây?', '{"A":{"text":"Hỗ trợ quyết định đầu tư, phát hiện và ngăn chặn gian lận, nâng cao trải nghiệm khách hàng trong lĩnh vực tài chính, ngân hàng.","image":""},"B":{"text":"Cải thiện hiệu suất, hiệu quả của các lĩnh vực sản xuất.","image":""},"C":{"text":"Giúp giám sát môi trường tự nhiên và theo dõi tình hình biến đổi khí hậu.","image":""},"D":{"text":"Phát triển các nền tảng học trực tuyến thông minh.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('87621039-4713-4cbf-9628-5efd6476c591', '4-1', 'TH', 'TIN 12 - BAI 2', 'Phát biểu nào sau đây đúng?', '{"A":{"text":"Các thành tựu hiện tại của AI đều là Trí tuệ nhân tạo tổng quát.","image":""},"B":{"text":"Phiên bản GPT-2 được huấn luyện trên hàng vạn văn bản thuộc nhiều lĩnh vực khác nhau trên Internet, bao gồm sách, bài báo, trang web và nhiều nguồn khác.","image":""},"C":{"text":"Nhiều chuyên gia coi ChatGPT là bước đột phá trong lĩnh vực AI của năm 2022.","image":""},"D":{"text":"ChatGPT có thể làm thơ, soạn nhạc, viết thư, thiết kế nhưng không thể sửa lỗi trong lập trình.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('43ba3df1-f517-4aa7-bfcd-ccbc7af668ca', '4-1', 'TH', 'TIN 12 - BAI 2', 'Phát biểu nào sau đây nói về sự phát triển của AI kéo theo rủi ro về an ninh, an toàn?', '{"A":{"text":"Nhiều ứng dụng AI hoạt động dựa vào việc thu thập một lượng lớn dữ liệu cá nhân, điều này làm tăng mối lo ngại về quyền riêng tư có khả năng bị lạm dụng.","image":""},"B":{"text":"Phần lớn các ứng dụng AI hiện nay đều là các “hộp đen”, gây khó khăn cho việc hiểu các quyết định được đưa ra như thế nào, dẫn đến việc thiếu trách nhiệm giải trình để đảm bảo tính minh bạch.","image":""},"C":{"text":"AI có khả năng tự động hoá nhiều công việc, dẫn đến tình trạng thất nghiệp và tạo nên nhiều nguy cơ cho sự phát triển xã hội.","image":""},"D":{"text":"Nhiều ứng dụng AI được xây dựng và triển khai trực tuyến nên có thể bị xâm nhập hoặc tấn công thay đổi dữ liệu và mô hình dẫn đến những quyết định không chính xác do AI đưa ra.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('68cadc06-8d21-4a98-b3f3-f0463424b7b1', '4-1', 'VD', 'TIN 12 - BAI 2', 'Một trong những lợi ích quan trọng của AI trong nông nghiệp là lợi ích nào sau đây?', '{"A":{"text":"Tăng cường các hoạt động ngoại khóa.","image":""},"B":{"text":"Tối ưu hoá quy trình chăm sóc vật nuôi và cây trồng.","image":""},"C":{"text":"Phân tích hành vi người tiêu dùng.","image":""},"D":{"text":"Giảm chi phí vận hành giao thông.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('6687af52-1acf-4272-933f-fbaebc30e4df', '4-1', 'VD', 'TIN 12 - BAI 2', 'Khả năng nào sau đây của ChatGPT giúp nó trả lời câu hỏi của người dùng một cách tự nhiên?', '{"A":{"text":"Ghi nhớ các câu hỏi trước đó.","image":""},"B":{"text":"Thích nghi với ngữ cảnh của cuộc trò chuyện.","image":""},"C":{"text":"Đưa ra quyết định kinh doanh.","image":""},"D":{"text":"Tối ưu hóa giao thông.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:37', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('fb488850-131e-47fb-b490-c1a00f97e8f6', '4-1', 'VD', 'TIN 12 - BAI 2', 'Một trong các mục tiêu dài hạn của nghiên cứu AI là mục tiêu nào sau đây?', '{"A":{"text":"Phát triển AI có trí tuệ như con người.","image":""},"B":{"text":"Tối ưu hoá quy trình sản xuất.","image":""},"C":{"text":"Cải thiện khả năng nhận dạng hình ảnh.","image":""},"D":{"text":"Tăng tốc độ xử lý của máy tính.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:38', '2026-10-04T01:49:36.447Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('f27fa763-794b-4bf1-ab00-193167f8bdca', '4-1', 'VD', 'TIN 12 - BAI 2', 'Khi AI hoạt động như một “hộp đen” nó có thể gây ra vấn đề gì sau đây?', '{"A":{"text":"Thiếu minh bạch trong quá trình đưa ra quyết định.","image":""},"B":{"text":"Tăng hiệu suất giao thông.","image":""},"C":{"text":"Tăng năng suất lao động.","image":""},"D":{"text":"Tối ưu hóa các quy trình trong giáo dục.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('d5cb135e-623a-48b4-8d2d-293a29452055', '4-1', 'VD', 'TIN 12 - BAI 2', 'Nguy cơ lớn nhất đối với người lao động khi AI tự động hóa nhiều công việc là nguy cơ nào sau đây?', '{"A":{"text":"Giảm mức lương trung bình.","image":""},"B":{"text":"Gia tăng tình trạng thất nghiệp.","image":""},"C":{"text":"Tăng số giờ làm việc.","image":""},"D":{"text":"Giảm hiệu quả trong quản lý.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('ccaf2841-08b7-4141-9f9c-f158cd2da0c0', '4-1', 'VD', 'TIN 12 - BAI 2', 'Phương án nào sau đây là tên của hệ chuyên gia về Toán học?', '{"A":{"text":"DENDRAL.","image":""},"B":{"text":"MYCIN.","image":""},"C":{"text":"HEARSAY.","image":""},"D":{"text":"MACSYMA.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('5c41373e-b1ba-403c-bd6c-51b308b7f8ab', '4-1', 'VD', 'TIN 12 - BAI 2', 'Phương án nào sau đây là tên của một ứng dụng AI giúp xây dựng trải nghiệm giao tiếp tự nhiên?', '{"A":{"text":"TensorFlow.","image":""},"B":{"text":"Dialogflow.","image":""},"C":{"text":"Rainbird.","image":""},"D":{"text":"Origami.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('0370baf8-eee1-45ed-ba0d-fe1bd5961717', '4-1', 'VD', 'TIN 12 - BAI 2', 'Phương án nào sau đây là tên của một phần mềm AI giúp tạo hình ảnh dựa trên các miêu tả văn bản hoặc lời nói?', '{"A":{"text":"Codex.","image":""},"B":{"text":"Midjourney.","image":""},"C":{"text":"Whisper.","image":""},"D":{"text":"Rytr.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 13:14:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('8524054c-1eef-41f5-aed1-3113eedd139c', '4-1', 'NB', 'TIN 12 - BAI 3', 'Trong mạng cục bộ (LAN), thiết bị nào sau đây được dùng để kết nối các máy tính trực tiếp qua cáp mạng?', '{"A":{"text":"Router.","image":""},"B":{"text":"Hub và Switch.","image":""},"C":{"text":"Modem.","image":""},"D":{"text":"Wireless Access Point (WAP).","image":""}}', 'B', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:51', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('1bd3dc66-bcdc-407d-b400-38a40032c6f2', '4-1', 'NB', 'TIN 12 - BAI 3', 'Thiết bị mạng nào sau đây giúp phát tán tín hiệu đến tất cả các cổng khi một máy tính gửi dữ liệu qua nó?', '{"A":{"text":"Switch.","image":""},"B":{"text":"Hub.","image":""},"C":{"text":"Router.","image":""},"D":{"text":"Modem.","image":""}}', 'B', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:51', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('1e4674f4-1818-421f-9042-2b7e71004f2a', '4-1', 'NB', 'TIN 12 - BAI 3', 'Trong một LAN lớn có từ vài chục đến hàng trăm máy tính, thiết bị nào sau đây nên được sử dụng để giảm thiểu xung đột tín hiệu?', '{"A":{"text":"Hub.","image":""},"B":{"text":"Modem.","image":""},"C":{"text":"Switch.","image":""},"D":{"text":"Access Point.","image":""}}', 'C', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:51', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('6d3e441a-270a-4ff3-b334-c86203234303', '4-1', 'NB', 'TIN 12 - BAI 3', 'Wi-Fi là tên viết tắt của cụm từ nào sau đây?', '{"A":{"text":"Wireless Fidelity.","image":""},"B":{"text":"Wired Fidelity.","image":""},"C":{"text":"Wireless Network.","image":""},"D":{"text":"Wired Network.","image":""}}', 'A', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:51', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
