INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('b8d4286b-c6ae-446b-8bae-f2caf2568428', '4-1', 'NB', 'TIN 12 - BAI 3', 'Khi router có nhiều cổng WAN, nó cần thực hiện tác vụ nào sau đây?', '{"A":{"text":"Chọn cổng phù hợp để chuyển dữ liệu.","image":""},"B":{"text":"Chuyển đổi tín hiệu từ analog sang digital.","image":""},"C":{"text":"Tự động sửa lỗi mạng.","image":""},"D":{"text":"Kết nối các máy tính trong LAN.","image":""}}', 'A', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:51', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
