INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('4a8691a2-3f75-4183-9e68-afd8d82a1408', '4-1', 'TH', 'TIN 12 - BAI 3', 'Loại modem nào sau đây cho phép nối hai máy tính qua hệ thống chuyển mạch của mạng điện thoại công cộng?', '{"A":{"text":"Modem quay số.","image":""},"B":{"text":"Modem GSM 3G, 4G, 5G,…","image":""},"C":{"text":"Modem ADSL.","image":""},"D":{"text":"Modem quang.\nTHÔNG HIỂU","image":""}}', 'A', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:52', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('3ae65b61-5355-4c99-a346-1579b4587b16', '4-1', 'TH', 'TIN 12 - BAI 3', 'Trong một mạng LAN nhỏ ở gia đình, lý do nào sau đây khiến người dùng có thể sử dụng hub thay vì switch?', '{"A":{"text":"Vì hub có nhiều cổng hơn.","image":""},"B":{"text":"Vì hub rẻ hơn và không cần thiết dùng switch với ít thiết bị.","image":""},"C":{"text":"Vì hub giúp tăng hiệu suất truyền dữ liệu.","image":""},"D":{"text":"Vì hub ít gây xung đột tín hiệu hơn.","image":""}}', 'B', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:52', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('409f2b6a-9668-459a-9ade-497787cab701', '4-1', 'TH', 'TIN 12 - BAI 3', 'Lý do nào sau đây Wireless Access Point còn được gọi là “điểm truy cập không dây”?', '{"A":{"text":"Vì chỉ kết nối thiết bị qua cáp.","image":""},"B":{"text":"Vì nó là một router kết nối các LAN.","image":""},"C":{"text":"Vì giúp kết nối các thiết bị không dây trong mạng cục bộ.","image":""},"D":{"text":"Vì giúp tăng tốc độ truyền dữ liệu trong mạng.","image":""}}', 'C', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:52', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('4fa493ff-ae9f-4295-867c-45b400f858b3', '4-1', 'TH', 'TIN 12 - BAI 3', 'Trong một router gia đình, cổng nào sau đây kết nối trực tiếp đến nhà cung cấp dịch vụ Internet?', '{"A":{"text":"Cổng LAN.","image":""},"B":{"text":"Cổng WAN.","image":""},"C":{"text":"Cổng USB.","image":""},"D":{"text":"Cổng Ethernet.","image":""}}', 'B', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:52', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('7fae1e57-007c-4c06-ab9d-f6fb324cc1a4', '4-1', 'TH', 'TIN 12 - BAI 3', 'Lý do nào sau đây một số mạng gia đình cần sử dụng modem?', '{"A":{"text":"Vì modem làm tăng tốc độ mạng.","image":""},"B":{"text":"Vì modem chuyển tín hiệu số thành tín hiệu tương tự và ngược lại.","image":""},"C":{"text":"Vì modem có nhiều cổng hơn router.","image":""},"D":{"text":"Vì modem có thể tự động sửa lỗi mạng.","image":""}}', 'B', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:52', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('a06483fe-22b1-4061-808f-2cadb19f4f0e', '4-1', 'TH', 'TIN 12 - BAI 3', 'Thiết bị nào sau đây xác định cổng kết nối giữa thiết bị gửi và thiết bị nhận, sau đó thiết lập tạm thời kênh truyền giữa hai cổng kết nối để truyền dữ liệu và huỷ kết nối sau khi hoàn thành việc truyền?', '{"A":{"text":"Switch.","image":""},"B":{"text":"Router.","image":""},"C":{"text":"Hub.","image":""},"D":{"text":"Modem.","image":""}}', 'A', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:52', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('e5302027-b393-4428-b5bb-a435dc57621e', '4-1', 'TH', 'TIN 12 - BAI 3', 'Phát biểu nào sau đây đúng?', '{"A":{"text":"Mạng viễn thông sử dụng các modem để chuyển tiếp dữ liệu.","image":""},"B":{"text":"Thông thường LAN kết nối có dây các máy tính qua các thiết bị như switch hay hub trong một phạm vi địa lí nhất định.","image":""},"C":{"text":"Khi dùng hub thì tín hiệu đi từ máy gửi đến máy nhận sẽ không gây xung đột với tín hiệu của các cuộc truyền ở cổng khác.","image":""},"D":{"text":"Switch có chi phí rẻ hơn rất nhiều so với một hub có cùng số cổng.","image":""}}', 'B', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:52', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('f5c1473d-94f6-465f-9c06-ba4956f0fd35', '4-1', 'TH', 'TIN 12 - BAI 3', 'Wireless Access Point (WAP) có chức năng nào sau đây?', '{"A":{"text":"Chuyển đổi tín hiệu từ tín hiệu số sang tín hiệu tương tự và ngược lại, thường dùng khi kết nối LAN với Internet.","image":""},"B":{"text":"Dùng để kết nối các máy tính trong cùng LAN trực tiếp qua cáp mạng.","image":""},"C":{"text":"Dùng để kết nối các thiết bị đầu cuối qua sóng Wi-Fi giúp giảm chi phí thiết lập LAN hoặc kết nối với một LAN để mở rộng phạm vi làm việc.","image":""},"D":{"text":"Dùng để dẫn đường cho dữ liệu khi kết nối trên mạng diện rộng như Internet.\nVẬN DỤNG","image":""}}', 'C', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:52', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('a42ad884-ad1f-4f62-b827-cbdfb58628a7', '4-1', 'VD', 'TIN 12 - BAI 3', 'Trong một mạng lớn, để giảm thiểu chi phí và tránh xung đột tín hiệu, cách tốt nhất là sử dụng kết hợp thiết bị nào sau đây?', '{"A":{"text":"Một router duy nhất.","image":""},"B":{"text":"Một switch kết hợp với hub ở tầng cuối.","image":""},"C":{"text":"Chỉ sử dụng nhiều hub.","image":""},"D":{"text":"Chỉ sử dụng nhiều switch.","image":""}}', 'B', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:52', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('a9c0bb30-5678-4861-a6ca-bf6e6686a3e8', '4-1', 'VD', 'TIN 12 - BAI 3', 'Khi muốn mở rộng phạm vi địa lý của mạng LAN, thiết bị nào sau đây có thể được thêm vào?', '{"A":{"text":"Switch.","image":""},"B":{"text":"Hub.","image":""},"C":{"text":"Wireless Access Point.","image":""},"D":{"text":"Router với nhiều cổng LAN.","image":""}}', 'C', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:52', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('12bf5688-dcb1-4f11-b12d-2015772d94ca', '4-1', 'VD', 'TIN 12 - BAI 3', 'Khi truyền dữ liệu giữa hai máy tính ở hai LAN khác nhau, lý do nào sau đây dữ liệu phải chuyển qua cổng LAN và sau đó qua cổng WAN của router?', '{"A":{"text":"Để chuyển đổi từ tín hiệu số sang tín hiệu tương tự.","image":""},"B":{"text":"Để đảm bảo dữ liệu được định tuyến qua Internet.","image":""},"C":{"text":"Để tránh xung đột tín hiệu trong LAN.","image":""},"D":{"text":"Để bảo mật dữ liệu trong LAN.","image":""}}', 'B', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:52', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('264cd3b3-91b9-4a2e-8adf-e142d02c5199', '4-1', 'VD', 'TIN 12 - BAI 3', 'Trong trường hợp kết nối Internet không ổn định, thiết bị nào sau đây sẽ hữu ích để giúp router điều chỉnh tín hiệu mạng?', '{"A":{"text":"Hub.","image":""},"B":{"text":"Switch.","image":""},"C":{"text":"Modem.","image":""},"D":{"text":"Access Point.","image":""}}', 'C', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:52', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('410dad8d-13b2-46eb-84e7-21319c7307f8', '4-1', 'VD', 'TIN 12 - BAI 3', 'Khi sử dụng mạng di động (3G, 4G, 5G) để truyền dữ liệu từ LAN ra bên ngoài, loại modem nào sau đây thường được dùng?', '{"A":{"text":"Modem quay số (dial-up).","image":""},"B":{"text":"Modem ADSL.","image":""},"C":{"text":"Modem quang.","image":""},"D":{"text":"Modem GSM.","image":""}}', 'D', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:53', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('40ed3b58-fc2d-48e0-b805-7939b55e3e8b', '4-1', 'VD', 'TIN 12 - BAI 3', 'Các LAN thường dùng loại cáp mạng nào?', '{"A":{"text":"FTP.","image":""},"B":{"text":"STP.","image":""},"C":{"text":"ETP.","image":""},"D":{"text":"UTP.","image":""}}', 'D', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:53', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('37f4cf2f-b55c-4aad-9d20-2916848ab420', '4-1', 'VD', 'TIN 12 - BAI 3', 'Khi kết nối máy tính với các thiết bị mạng, cần cắm một đầu giắc của cáp vào cổng nào của máy tính?', '{"A":{"text":"RJ45.","image":""},"B":{"text":"VJ45.","image":""},"C":{"text":"CJ45.","image":""},"D":{"text":"PJ45.","image":""}}', 'A', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:53', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('d38b9c40-2c59-466a-bae2-deeceaf3d702', '4-1', 'VD', 'TIN 12 - BAI 3', 'Phát biểu nào sau đây là sai?', '{"A":{"text":"Switch dùng để kết nối các đoạn mạng với nhau theo mô hình hình sao.","image":""},"B":{"text":"Hiện nay có hai loại Hub phổ biến là Active Hub và Smart Hub.","image":""},"C":{"text":"Router là một thiết bị mạng thuộc lớp 2 của mô hình OSI (Network Layer).","image":""},"D":{"text":"Modem có chức năng chuyển hoá các gói dữ liệu từ nhà cung cấp dịch vụ mạng (ISP) thành các kết nối Internet cho các router hoặc các thiết bị liên kết mạng khác qua địa chỉ IP.","image":""}}', 'C', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-17 14:45:53', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
