INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('b34842c6-8a2f-42b4-9432-348c6da73712', '4-1', 'NB', 'TIN 12 - BAI 3', 'Trong một LAN lớn có từ vài chục đến hàng trăm máy tính, thiết bị nào sau đây nên được sử dụng để giảm thiểu xung đột tín hiệu?', '{"A":{"text":"Hub.","image":""},"B":{"text":"Modem.","image":""},"C":{"text":"Switch.","image":""},"D":{"text":"Access Point.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:47', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
