INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('ad348b1a-8ca7-44d1-b4c2-7411da663258', '4-1', 'NB', 'TIN 12 - BAI 3', 'Switch khác với hub ở điểm nào sau đây?', '{"A":{"text":"Switch chỉ gửi tín hiệu đến thiết bị nhận.","image":""},"B":{"text":"Switch phát tín hiệu đến tất cả các cổng.","image":""},"C":{"text":"Switch không sử dụng trong mạng LAN.","image":""},"D":{"text":"Switch gây xung đột tín hiệu nhiều hơn.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('11b3b629-ff3c-4ecc-b04f-65aa3d22e7ad', '4-1', 'NB', 'TIN 12 - BAI 3', 'Mạng cục bộ còn có tên gọi là mạng nào sau đây?', '{"A":{"text":"Mạng WAN.","image":""},"B":{"text":"Mạng PAN.","image":""},"C":{"text":"Mạng MAN.","image":""},"D":{"text":"Mạng LAN.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('43b1bbee-cf25-40f9-b080-e3ae9773ab49', '4-1', 'NB', 'TIN 12 - BAI 3', 'Router là thiết bị nào sau đây?', '{"A":{"text":"Bộ chuyển mạch.","image":""},"B":{"text":"Bộ thu phát không dây.","image":""},"C":{"text":"Bộ định tuyến.","image":""},"D":{"text":"Bộ chia tín hiệu.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('bb5cc7dd-8265-46e9-a644-e2538004431c', '4-1', 'NB', 'TIN 12 - BAI 3', 'Wi-Fi sử dụng loại sóng nào sau đây để truyền dữ liệu?', '{"A":{"text":"Sóng điện từ.","image":""},"B":{"text":"Sóng vô tuyến điện.","image":""},"C":{"text":"Sóng ánh sáng.","image":""},"D":{"text":"Sóng mang.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('0d4a1ffe-a65e-4444-befb-b3bca77c19d5', '4-1', 'TH', 'TIN 12 - BAI 3', 'Loại modem nào sau đây cho phép nối hai máy tính qua hệ thống chuyển mạch của mạng điện thoại công cộng?', '{"A":{"text":"Modem quay số.","image":""},"B":{"text":"Modem GSM 3G, 4G, 5G,…","image":""},"C":{"text":"Modem ADSL.","image":""},"D":{"text":"Modem quang.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('9049aace-0b0b-4c15-9aab-d4fb963d4685', '4-1', 'TH', 'TIN 12 - BAI 3', 'Trong một mạng LAN nhỏ ở gia đình, lý do nào sau đây khiến người dùng có thể sử dụng hub thay vì switch?', '{"A":{"text":"Vì hub có nhiều cổng hơn.","image":""},"B":{"text":"Vì hub rẻ hơn và không cần thiết dùng switch với ít thiết bị.","image":""},"C":{"text":"Vì hub giúp tăng hiệu suất truyền dữ liệu.","image":""},"D":{"text":"Vì hub ít gây xung đột tín hiệu hơn.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('ca6009a9-a00c-439e-accf-c3ea025db094', '4-1', 'TH', 'TIN 12 - BAI 3', 'Lý do nào sau đây Wireless Access Point còn được gọi là “điểm truy cập không dây”?', '{"A":{"text":"Vì chỉ kết nối thiết bị qua cáp.","image":""},"B":{"text":"Vì nó là một router kết nối các LAN.","image":""},"C":{"text":"Vì giúp kết nối các thiết bị không dây trong mạng cục bộ.","image":""},"D":{"text":"Vì giúp tăng tốc độ truyền dữ liệu trong mạng.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('2099a5ad-9daa-4269-b1d8-7b998dbbc8e7', '4-1', 'TH', 'TIN 12 - BAI 3', 'Trong một router gia đình, cổng nào sau đây kết nối trực tiếp đến nhà cung cấp dịch vụ Internet?', '{"A":{"text":"Cổng LAN.","image":""},"B":{"text":"Cổng WAN.","image":""},"C":{"text":"Cổng USB.","image":""},"D":{"text":"Cổng Ethernet.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('284230be-5511-4b0f-9e2a-779796429d0a', '4-1', 'TH', 'TIN 12 - BAI 3', 'Lý do nào sau đây một số mạng gia đình cần sử dụng modem?', '{"A":{"text":"Vì modem làm tăng tốc độ mạng.","image":""},"B":{"text":"Vì modem chuyển tín hiệu số thành tín hiệu tương tự và ngược lại.","image":""},"C":{"text":"Vì modem có nhiều cổng hơn router.","image":""},"D":{"text":"Vì modem có thể tự động sửa lỗi mạng.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('1195bd3f-8cdc-49f6-87f6-71ee8de51b57', '4-1', 'TH', 'TIN 12 - BAI 3', 'Thiết bị nào sau đây xác định cổng kết nối giữa thiết bị gửi và thiết bị nhận, sau đó thiết lập tạm thời kênh truyền giữa hai cổng kết nối để truyền dữ liệu và huỷ kết nối sau khi hoàn thành việc truyền?', '{"A":{"text":"Switch.","image":""},"B":{"text":"Router.","image":""},"C":{"text":"Hub.","image":""},"D":{"text":"Modem.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('cc12a6dc-b5a6-4bd6-a0da-8f5d6f3a3d1f', '4-1', 'TH', 'TIN 12 - BAI 3', 'Phát biểu nào sau đây đúng?', '{"A":{"text":"Mạng viễn thông sử dụng các modem để chuyển tiếp dữ liệu.","image":""},"B":{"text":"Thông thường LAN kết nối có dây các máy tính qua các thiết bị như switch hay hub trong một phạm vi địa lí nhất định.","image":""},"C":{"text":"Khi dùng hub thì tín hiệu đi từ máy gửi đến máy nhận sẽ không gây xung đột với tín hiệu của các cuộc truyền ở cổng khác.","image":""},"D":{"text":"Switch có chi phí rẻ hơn rất nhiều so với một hub có cùng số cổng.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('8284fce6-5aa4-4c99-b7d6-065ce3044a5f', '4-1', 'TH', 'TIN 12 - BAI 3', 'Wireless Access Point (WAP) có chức năng nào sau đây?', '{"A":{"text":"Chuyển đổi tín hiệu từ tín hiệu số sang tín hiệu tương tự và ngược lại, thường dùng khi kết nối LAN với Internet.","image":""},"B":{"text":"Dùng để kết nối các máy tính trong cùng LAN trực tiếp qua cáp mạng.","image":""},"C":{"text":"Dùng để kết nối các thiết bị đầu cuối qua sóng Wi-Fi giúp giảm chi phí thiết lập LAN hoặc kết nối với một LAN để mở rộng phạm vi làm việc.","image":""},"D":{"text":"Dùng để dẫn đường cho dữ liệu khi kết nối trên mạng diện rộng như Internet.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('dc727ed8-0196-4247-ac7d-4c8589696fcb', '4-1', 'VD', 'TIN 12 - BAI 3', 'Trong một mạng lớn, để giảm thiểu chi phí và tránh xung đột tín hiệu, cách tốt nhất là sử dụng kết hợp thiết bị nào sau đây?', '{"A":{"text":"Một router duy nhất.","image":""},"B":{"text":"Một switch kết hợp với hub ở tầng cuối.","image":""},"C":{"text":"Chỉ sử dụng nhiều hub.","image":""},"D":{"text":"Chỉ sử dụng nhiều switch.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('ab279a08-46d8-4a89-a4a3-27e7ebf9deef', '4-1', 'VD', 'TIN 12 - BAI 3', 'Khi muốn mở rộng phạm vi địa lý của mạng LAN, thiết bị nào sau đây có thể được thêm vào?', '{"A":{"text":"Switch.","image":""},"B":{"text":"Hub.","image":""},"C":{"text":"Wireless Access Point.","image":""},"D":{"text":"Router với nhiều cổng LAN.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:49', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('2b318159-49bb-449f-b297-fb9fbe25ec4f', '4-1', 'VD', 'TIN 12 - BAI 3', 'Khi truyền dữ liệu giữa hai máy tính ở hai LAN khác nhau, lý do nào sau đây dữ liệu phải chuyển qua cổng LAN và sau đó qua cổng WAN của router?', '{"A":{"text":"Để chuyển đổi từ tín hiệu số sang tín hiệu tương tự.","image":""},"B":{"text":"Để đảm bảo dữ liệu được định tuyến qua Internet.","image":""},"C":{"text":"Để tránh xung đột tín hiệu trong LAN.","image":""},"D":{"text":"Để bảo mật dữ liệu trong LAN.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:49', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('5f22a513-a206-4ffe-b11b-40e230d59fef', '4-1', 'VD', 'TIN 12 - BAI 3', 'Trong trường hợp kết nối Internet không ổn định, thiết bị nào sau đây sẽ hữu ích để giúp router điều chỉnh tín hiệu mạng?', '{"A":{"text":"Hub.","image":""},"B":{"text":"Switch.","image":""},"C":{"text":"Modem.","image":""},"D":{"text":"Access Point.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:49', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('c4c9a7d8-f075-4e8b-b38a-abd911659f8d', '4-1', 'VD', 'TIN 12 - BAI 3', 'Khi sử dụng mạng di động (3G, 4G, 5G) để truyền dữ liệu từ LAN ra bên ngoài, loại modem nào sau đây thường được dùng?', '{"A":{"text":"Modem quay số (dial-up).","image":""},"B":{"text":"Modem ADSL.","image":""},"C":{"text":"Modem quang.","image":""},"D":{"text":"Modem GSM.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:49', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
