INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('18694c7d-2337-4cfc-a955-7037edb9e39b', '4-1', 'TH', 'TIN HOC 12 - BAI 4', 'Phát biểu nào sau đây sai?', '{"A":{"text":"Theo phương pháp định tuyến tĩnh, mỗi router có một bảng định tuyến.","image":""},"B":{"text":"Giao thức TCP đảm bảo việc truyền dữ liệu theo từng ứng dụng một cách chính xác, tin cậy và hiệu quả.","image":""},"C":{"text":"MAC là địa chỉ vật lí của máy tính.","image":""},"D":{"text":"Giao thức IP đảm bảo chuyển dữ liệu từ mạng này đến mạng kia và chuyển dữ liệu đến một ứng dụng cụ thể trên một máy cụ thể.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:34', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('38c5574e-19e8-45fc-9be8-5c763fb8aaaa', '4-1', 'TH', 'TIN HOC 12 - BAI 4', 'Giao thức nào sau đây quy định cách biểu diễn (mã hoá) các trang web?', '{"A":{"text":"SNMP.","image":""},"B":{"text":"DNS.","image":""},"C":{"text":"HTTP.","image":""},"D":{"text":"DHCP.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:34', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('97a3ec0b-1de6-4cc1-9fdd-dcb0fc6e9caf', '4-1', 'TH', 'TIN HOC 12 - BAI 4', 'Lý do nào sau đây giao thức TCP được coi là giao thức kiểm soát truyền dữ liệu ổn định?', '{"A":{"text":"Vì nó chỉ truyền dữ liệu trong mạng LAN.","image":""},"B":{"text":"Vì nó định danh thiết bị qua địa chỉ IP.","image":""},"C":{"text":"Vì nó có cơ chế kiểm tra lỗi và khôi phục dữ liệu.","image":""},"D":{"text":"Vì nó là giao thức phổ biến nhất.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:35', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('08210424-5cfe-4551-8cb7-17b41559dd12', '4-1', 'TH', 'TIN HOC 12 - BAI 4', 'Khi sử dụng giao thức POP3 hoặc IMAP, dữ liệu nào sau đây được lấy từ máy chủ?', '{"A":{"text":"Trang web.","image":""},"B":{"text":"Thư điện tử (email).","image":""},"C":{"text":"Tên miền.","image":""},"D":{"text":"Địa chỉ IP.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:35', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('3409fad4-4f45-4c95-8860-2a3ad3577ab1', '4-1', 'TH', 'TIN HOC 12 - BAI 4', 'Địa chỉ MAC đóng vai trò gì sau đây trong giao thức Ethernet?', '{"A":{"text":"Định tuyến dữ liệu qua mạng.","image":""},"B":{"text":"Xác định thiết bị trong mạng cục bộ.","image":""},"C":{"text":"Mã hoá dữ liệu truyền đi.","image":""},"D":{"text":"Kiểm tra lỗi truyền dữ liệu.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:35', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('1e05e8bb-98cf-4cdd-94c6-865cbdb4013e', '4-1', 'TH', 'TIN HOC 12 - BAI 4', 'Giao thức DNS có vai trò nào sau đây trong mạng Internet?', '{"A":{"text":"Định tuyến dữ liệu.","image":""},"B":{"text":"Kiểm tra lỗi truyền dữ liệu.","image":""},"C":{"text":"Gửi thư điện tử.","image":""},"D":{"text":"Chuyển đổi tên miền thành địa chỉ IP.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:35', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('9ffc9d40-8c78-4a77-9faa-0525706e9574', '4-1', 'TH', 'TIN HOC 12 - BAI 4', 'Quy định về mã kiểm tra trong giao thức Ethernet có mục đích gì sau đây?', '{"A":{"text":"Định danh thiết bị.","image":""},"B":{"text":"Phát hiện lỗi truyền.","image":""},"C":{"text":"Tăng tốc độ truyền.","image":""},"D":{"text":"Kết nối các mạng LAN.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:35', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('8324db3f-c16b-4a16-99b8-d9dfed7b2448', '4-1', 'VD', 'TIN HOC 12 - BAI 4', 'Trong mạng Internet, khi một router nhận được gói dữ liệu, nó cần thực hiện bước nào sau đây để chuyển tiếp dữ liệu tới đích?', '{"A":{"text":"Gán địa chỉ MAC cho dữ liệu.","image":""},"B":{"text":"Chọn cổng thích hợp dựa trên bảng định tuyến.","image":""},"C":{"text":"Kiểm tra mã kiểm tra lỗi.","image":""},"D":{"text":"Đổi địa chỉ IP của dữ liệu.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:35', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('fb9c8ea9-4474-4fb9-a515-f8e028649924', '4-1', 'VD', 'TIN HOC 12 - BAI 4', 'Trong quá trình truyền dữ liệu, nếu gói tin bị thất lạc, giao thức TCP sẽ thực hiện tác vụ nào sau đây?', '{"A":{"text":"Thay đổi địa chỉ MAC của gói tin.","image":""},"B":{"text":"Yêu cầu gửi lại gói tin bị mất.","image":""},"C":{"text":"Tăng tốc độ truyền dữ liệu.","image":""},"D":{"text":"Đóng kết nối giữa các thiết bị.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:35', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('3808f600-373f-4869-9d75-b3121a211412', '4-1', 'VD', 'TIN HOC 12 - BAI 4', 'Nếu muốn đảm bảo dữ liệu từ một ứng dụng cụ thể đến đúng ứng dụng nhận trên máy đích, giao thức TCP sẽ thực hiện việc nào sau đây?', '{"A":{"text":"Thêm địa chỉ IP vào dữ liệu.","image":""},"B":{"text":"Kiểm tra mã MAC.","image":""},"C":{"text":"Gán nhãn cổng ứng dụng cho gói dữ liệu.","image":""},"D":{"text":"Đánh số thứ tự cho mỗi byte dữ liệu.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:35', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('3b092f1d-852f-43c2-8d6b-fb78ce18650d', '4-1', 'VD', 'TIN HOC 12 - BAI 4', 'Phương pháp định tuyến động giúp router điều chỉnh lộ trình dữ liệu trong trường hợp nào sau đây?', '{"A":{"text":"Khi các thiết bị trong mạng thay đổi địa chỉ IP.","image":""},"B":{"text":"Khi điều kiện mạng thay đổi.","image":""},"C":{"text":"Khi sử dụng mạng cục bộ.","image":""},"D":{"text":"Khi kết nối qua cổng LAN.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:35', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('864a7df2-05a6-4b49-aef1-1df53ad56542', '4-1', 'VD', 'TIN HOC 12 - BAI 4', 'Giao thức HTTP có vai trò gì sau đây trong truyền dữ liệu trên Internet?', '{"A":{"text":"Kiểm tra lỗi truyền dữ liệu.","image":""},"B":{"text":"Định danh thiết bị trong mạng.","image":""},"C":{"text":"Quy định cách mã hoá và biểu diễn trang web.","image":""},"D":{"text":"Phân bổ địa chỉ IP cho thiết bị.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:35', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
