INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('3c3d2589-1750-406e-93ba-df6d3ecd6e17', '4-1', 'NB', 'TIN HOC 12 - BAI 5', 'Thiết lập nào sau đây cần thực hiện để huỷ bỏ chia sẻ thư mục?', '{"A":{"text":"Chọn chế độ công khai.","image":""},"B":{"text":"Chuyển chế độ chia sẻ sang riêng tư.","image":""},"C":{"text":"Tắt tính năng chia sẻ.","image":""},"D":{"text":"Đặt lại quyền truy cập.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:36', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('cf898e7c-1215-4c58-b717-ac3c35ffc038', '4-1', 'NB', 'TIN HOC 12 - BAI 5', 'Để chia sẻ máy in, máy tính cung cấp dịch vụ in cần thiết lập chế độ nào sau đây?', '{"A":{"text":"Chế độ bảo mật.","image":""},"B":{"text":"Chế độ chia sẻ.","image":""},"C":{"text":"Chế độ in mặc định.","image":""},"D":{"text":"Chế độ in riêng tư.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:36', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
