INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('96c5f8bb-8600-45f3-97af-e07fe69f06f9', '4-1', 'NB', 'TIN HOC 12 - BAI 5', 'Thư mục nào sau đây là thư mục mặc định không chia sẻ trong hệ thống?', '{"A":{"text":"Documents.","image":""},"B":{"text":"Public.","image":""},"C":{"text":"Downloads.","image":""},"D":{"text":"Pictures.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:36', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('38325d91-1616-4006-8e03-5a1fdfe21a6c', '4-1', 'NB', 'TIN HOC 12 - BAI 5', 'Bước cuối cùng để hoàn tất chia sẻ một thư mục là bước nào sau đây?', '{"A":{"text":"Đặt quyền cho người dùng.","image":""},"B":{"text":"Thêm người dùng được chia sẻ.","image":""},"C":{"text":"Nháy chuột vào nút Apply.","image":""},"D":{"text":"Tắt tường lửa.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:36', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('72416487-471a-4e6b-a8dc-df2f8491bf3a', '4-1', 'NB', 'TIN HOC 12 - BAI 5', 'Trong thiết lập chia sẻ, quyền mặc định của người dùng mới được thêm vào là quyền nào sau đây?', '{"A":{"text":"Không có quyền.","image":""},"B":{"text":"Chỉ đọc.","image":""},"C":{"text":"Đọc và sửa.","image":""},"D":{"text":"Chỉ sửa.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:36', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('28c18c7b-de15-4d41-b7b3-9cc2e9e9177f', '4-1', 'NB', 'TIN HOC 12 - BAI 5', 'Khi chia sẻ tệp trên máy cục bộ, dữ liệu sẽ được lưu ở thư mục nào?', '{"A":{"text":"Documents.","image":""},"B":{"text":"System (C) → Users → Public.","image":""},"C":{"text":"Downloads.","image":""},"D":{"text":"Desktop.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:36', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('c0735f87-32f2-4fca-b6fe-9ce95d90f969', '4-1', 'NB', 'TIN HOC 12 - BAI 5', 'Nếu muốn huỷ chia sẻ một thư mục, bạn cần thực hiện thao tác nào sau đây?', '{"A":{"text":"Xóa thư mục.","image":""},"B":{"text":"Nháy chuột vào nút Sharing và bỏ dấu tích.","image":""},"C":{"text":"Tắt mạng cục bộ.","image":""},"D":{"text":"Thay đổi tên thư mục.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:36', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('9568778c-91a6-44e6-8730-3f8f785d0813', '4-1', 'NB', 'TIN HOC 12 - BAI 5', 'Chế độ khám phá mạng cần được đặt ở vị trí nào sau đây để máy tính xuất hiện trong danh sách mạng?', '{"A":{"text":"Off.","image":""},"B":{"text":"On.","image":""},"C":{"text":"Auto.","image":""},"D":{"text":"Public.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:37', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('4da966c8-746b-472d-b02c-d788d1b99bde', '4-1', 'TH', 'TIN HOC 12 - BAI 5', 'Lý do nào sau đây mà ta cần tắt tạm thời tường lửa khi chia sẻ tài nguyên trong mạng?', '{"A":{"text":"Để tăng tốc độ mạng.","image":""},"B":{"text":"Để bảo mật cao hơn.","image":""},"C":{"text":"Để máy tính khác có thể truy cập tài nguyên.","image":""},"D":{"text":"Để giảm tiêu hao tài nguyên hệ thống.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:37', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('26875ff6-adc3-45b4-854f-2a6406c1921f', '4-1', 'TH', 'TIN HOC 12 - BAI 5', 'Lựa chọn nào sau đây mô tả đúng về việc chia sẻ máy in trên mạng?', '{"A":{"text":"Mỗi máy tính đều cần cài đặt máy in riêng.","image":""},"B":{"text":"Máy chủ cần cài đặt và chia sẻ máy in.","image":""},"C":{"text":"Tất cả các máy tính phải có máy in vật lý riêng.","image":""},"D":{"text":"Không cần thiết lập chế độ chia sẻ cho máy in.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:37', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('37c2c8f4-3404-4149-bb17-dc4211158755', '4-1', 'TH', 'TIN HOC 12 - BAI 5', 'Bước nào sau đây là cần thiết để các máy tính khác sử dụng máy in mạng?', '{"A":{"text":"Tắt máy chủ.","image":""},"B":{"text":"Thiết lập tường lửa.","image":""},"C":{"text":"Khai báo sử dụng máy in mạng.","image":""},"D":{"text":"Cài đặt máy in cá nhân.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:37', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
