INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('67a0e5f4-7d99-4f21-9302-e40b9e09d8fe', '4-1', 'TH', 'TIN HOC 12 - BAI 5', 'Bước nào sau đây cần thực hiện để xác nhận máy in mạng đã được thiết lập thành công?', '{"A":{"text":"Chọn máy in.","image":""},"B":{"text":"Duyệt các máy tính trên mạng.","image":""},"C":{"text":"Chọn tùy chọn in mặc định.","image":""},"D":{"text":"Xác nhận thiết lập thành công.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:37', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('d14d436e-66bb-476b-9eb6-977ad6f6e515', '4-1', 'TH', 'TIN HOC 12 - BAI 5', 'Lý do nào sau đây cho biết việc chia sẻ tệp và máy in trên mạng cục bộ lại hữu ích?', '{"A":{"text":"Giúp máy tính hoạt động nhanh hơn.","image":""},"B":{"text":"Tiết kiệm không gian lưu trữ.","image":""},"C":{"text":"Giảm chi phí phần cứng và tăng cường tính tương tác.","image":""},"D":{"text":"Tăng bảo mật cho mạng nội bộ.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:37', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('7b2a35ed-8a3f-4cc5-90ea-eaef36fe22db', '4-1', 'TH', 'TIN HOC 12 - BAI 5', 'Trong một mạng LAN, để chia sẻ một máy in cho tất cả các máy tính, máy in cần phải được thiết lập nội dung nào sau đây?', '{"A":{"text":"Cài đặt trình điều khiển riêng cho mỗi máy tính.","image":""},"B":{"text":"Được kết nối với mạng thông qua máy tính trung gian.","image":""},"C":{"text":"Được kết nối trực tiếp với mạng và chia sẻ.","image":""},"D":{"text":"Không cần thiết lập gì.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:37', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('4bbedce5-8ce7-4f1e-9671-d57c202ded6d', '4-1', 'TH', 'TIN HOC 12 - BAI 5', 'Chức năng chia sẻ thư mục công cộng (Public Folder Sharing) có tác dụng gì trong các tác dụng sau đây?', '{"A":{"text":"Cho phép chia sẻ tệp với tất cả người dùng trên mạng.","image":""},"B":{"text":"Bảo mật tệp trong thư mục công cộng.","image":""},"C":{"text":"Giới hạn quyền truy cập tệp chỉ trong một nhóm người dùng.","image":""},"D":{"text":"Ngăn không cho người khác thấy nội dung tệp.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:37', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('af66838f-8f0b-402f-a661-93c6212722d6', '4-1', 'TH', 'TIN HOC 12 - BAI 5', 'Khi huỷ chia sẻ thư mục, điều gì sau đây sẽ xảy ra với quyền truy cập của người dùng khác?', '{"A":{"text":"Họ vẫn có quyền truy cập.","image":""},"B":{"text":"Quyền truy cập bị giới hạn.","image":""},"C":{"text":"Quyền truy cập bị mất hoàn toàn.","image":""},"D":{"text":"Tệp trong thư mục sẽ bị xóa.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:37', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('ea5d21da-91d0-421a-9f1b-99efe22b4008', '4-1', 'VD', 'TIN HOC 12 - BAI 5', 'Để bảo mật nhưng vẫn duy trì chia sẻ tệp, bạn nên thực hiện biện pháp nào sau đây?', '{"A":{"text":"Thiết lập tường lửa nhưng cho phép chia sẻ tệp.","image":""},"B":{"text":"Tắt hoàn toàn tường lửa.","image":""},"C":{"text":"Chỉ chia sẻ thư mục cá nhân.","image":""},"D":{"text":"Tắt chế độ phát hiện (discoverable).","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('a3cc9864-5534-42a4-a40b-3688dde5125c', '4-1', 'VD', 'TIN HOC 12 - BAI 5', 'Khi một thư mục không còn cần được chia sẻ, bước nào sau đây là hợp lý nhất để thực hiện?', '{"A":{"text":"Xóa thư mục.","image":""},"B":{"text":"Thay đổi quyền truy cập.","image":""},"C":{"text":"Tắt chia sẻ thư mục.","image":""},"D":{"text":"Thiết lập chế độ riêng tư.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('a0c219e8-b3e7-426a-96d6-ac6b6a53a5db', '4-1', 'VD', 'TIN HOC 12 - BAI 5', 'Điều kiện nào sau đây cần thiết để máy tính khác trong mạng có thể sử dụng máy in mạng?', '{"A":{"text":"Máy in phải ở chế độ in mặc định.","image":""},"B":{"text":"Máy tính phải được kết nối mạng.","image":""},"C":{"text":"Cần đăng nhập vào tài khoản máy chủ.","image":""},"D":{"text":"Máy in phải được chia sẻ.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('b94d8ca9-e69a-410d-a29a-8937d6988914', '4-1', 'VD', 'TIN HOC 12 - BAI 5', 'Nếu cần tăng tính bảo mật khi chia sẻ thư mục công cộng, bạn có thể thực hiện phương án nào sau đây?', '{"A":{"text":"Tăng quyền truy cập của thư mục.","image":""},"B":{"text":"Chuyển sang chế độ riêng tư.","image":""},"C":{"text":"Mở tường lửa.","image":""},"D":{"text":"Thêm máy tính mới vào mạng.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('f22b5cec-ac8d-4dca-b2b5-b8b595eeb8bd', '4-1', 'VD', 'TIN HOC 12 - BAI 5', 'Để đảm bảo chỉ một số máy tính trong mạng có quyền truy cập vào máy in, cần thực hiện thao tác nào sau đây?', '{"A":{"text":"Tắt chia sẻ máy in.","image":""},"B":{"text":"Thiết lập quyền truy cập máy in theo máy.","image":""},"C":{"text":"Chỉ dùng mạng công cộng.","image":""},"D":{"text":"Bật chế độ công khai.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('78426f54-9a55-4ca9-b8b0-1e91d0663ac2', '4-1', 'VD', 'TIN HOC 12 - BAI 5', 'Nếu bạn không nhìn thấy máy tính chia sẻ thư mục trên mạng, bước nào  sau đây cần kiểm tra đầu tiên?', '{"A":{"text":"Kết nối mạng của máy.","image":""},"B":{"text":"Cài đặt tường lửa.","image":""},"C":{"text":"Cài đặt quyền chia sẻ thư mục.","image":""},"D":{"text":"Địa chỉ IP của máy.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('c282c6c1-f7ad-4054-a0aa-8a909d80bc95', '4-1', 'VD', 'TIN HOC 12 - BAI 5', 'Khi thiết lập chia sẻ máy in, điều quan trọng nhất để các máy khác kết nối là thiết lập nào sau đây?', '{"A":{"text":"Cài đặt trình điều khiển trên từng máy tính.","image":""},"B":{"text":"Máy tính chia sẻ máy in phải đặt tên dễ nhớ.","image":""},"C":{"text":"Máy in phải được đặt là máy in mặc định.","image":""},"D":{"text":"Máy in phải có địa chỉ IP tĩnh.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('a9157646-942b-48cc-838e-377167809125', '4-1', 'VD', 'TIN HOC 12 - BAI 5', 'Điều kiện nào sau đây để người dùng khác có thể truy cập vào thư mục bạn chia sẻ trên máy tính của họ?', '{"A":{"text":"Họ phải được kết nối với mạng và nhìn thấy máy của bạn.","image":""},"B":{"text":"Họ phải đăng nhập bằng tài khoản của bạn.","image":""},"C":{"text":"Họ phải có cùng hệ điều hành.","image":""},"D":{"text":"Họ phải được cấp quyền sửa tệp.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('03a6e75c-c254-4309-bd6b-5808b1509fcf', '4-1', 'VD', 'TIN HOC 12 - BAI 5', 'Biện pháp nào sau đây có thể tăng cường tính bảo mật cho việc chia sẻ tệp trên mạng cục bộ?', '{"A":{"text":"Sử dụng mật khẩu bảo vệ thư mục chia sẻ.","image":""},"B":{"text":"Chỉ sử dụng mạng công cộng để chia sẻ.","image":""},"C":{"text":"Tắt chức năng tường lửa khi chia sẻ.","image":""},"D":{"text":"Cung cấp quyền truy cập đầy đủ cho tất cả người dùng.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('29438022-bc13-4d04-84e1-99292856d0b2', '4-1', 'VD', 'TIN HOC 12 - BAI 5', 'Để đảm bảo an toàn dữ liệu khi chia sẻ thư mục công cộng, nên thực hiện bước nào sau đây?', '{"A":{"text":"Bật tính năng tường lửa và giới hạn quyền truy cập.","image":""},"B":{"text":"Cho phép chia sẻ thư mục cho mọi người.","image":""},"C":{"text":"Xóa các tệp không cần thiết sau khi chia sẻ.","image":""},"D":{"text":"Chỉ chia sẻ với một số người dùng cụ thể.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-10-02 13:24:38', '2026-10-04T01:49:36.448Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
